<?php
declare(strict_types=1);
requireRole($user,['provincial_admin']);
if(!$portalReady)return;
$modern=ChurchPortal::officerRegistrationReady($db);
$extra=$modern?',r.requested_church_name,r.requested_church_type':'';
$pendingTotal=(int)$db->query("SELECT COUNT(*) FROM church_registrations WHERE status='pending'")->fetchColumn();
$pendingPages=max(1,(int)ceil($pendingTotal/12));$pendingPage=min($pendingPages,max(1,(int)(is_scalar($_GET['pending_page']??1)?($_GET['pending_page']??1):1)));$pendingOffset=($pendingPage-1)*12;
$requests=$db->query("SELECT r.id,r.full_name,r.email,r.phone,r.bank_name,r.account_name,r.account_last4,r.created_at,r.parish_id,h.node_name,h.node_type $extra FROM church_registrations r LEFT JOIN church_hierarchy h ON h.id=r.parish_id WHERE r.status='pending' ORDER BY r.id LIMIT 12 OFFSET $pendingOffset")->fetchAll();
$mailSummary=$db->prepare("SELECT SUM(status='pending') queued,SUM(status='failed' AND attempts>=3) failed FROM notification_outbox WHERE subject=?");$mailSummary->execute([ApprovalNotifications::SUBJECT]);$approvalMail=$mailSummary->fetch();
$reviewChurches=$modern?ChurchPortal::directory($db):[];
?>
<section class="panel pending-reps-panel" id="pending-reps"><div class="panel-heading"><div><h2>Officer registrations</h2><p class="section-kicker">PENDING REPRESENTATIVE APPROVALS</p><p>Verify identity and church authorization independently. Roles follow the linked Parish, Area or Zone.</p></div><span class="chip"><?= $pendingTotal ?> awaiting review</span></div><?php if((int)($approvalMail['failed']??0)>0): ?><p class="approval-mail-notice">Some approval emails could not be delivered. Check PHP mail and the approval-mail cron. Pending applications remain available here.</p><?php endif ?><?php if(!$requests): ?><div class="empty"><span>✓</span><h3>You’re all caught up</h3><p>New officer applications will appear here for approval.</p></div><?php endif ?>
<div class="pending-rep-grid"><?php foreach($requests as $request): ?><article class="review-card pending-rep-card"><div><span class="badge pending">Pending approval</span><h3><?= e($request['node_name'] ?? $request['requested_church_name'] ?? 'Unlinked church') ?></h3><p><?= e(ucfirst($request['node_type'] ?? $request['requested_church_type'] ?? 'Unknown level')) ?></p><p><?= e($request['full_name'].' · '.$request['email'].' · '.$request['phone']) ?></p><?php if($request['account_last4']!==''): ?><p class="muted small">Legacy church account: <?= e($request['bank_name'].' · '.$request['account_name'].' · ••••••'.$request['account_last4']) ?></p><?php endif ?></div><form method="post" class="review-actions"><?php hiddenAction('registration_review') ?><input type="hidden" name="registration_id" value="<?= (int)$request['id'] ?>">
<?php if(empty($request['parish_id'])): ?><p class="notice small">Unlisted name — check for similar churches. If genuinely absent, add it using Quick add with its correct parent and parish code, then return here and link it. Approval cannot create a church.</p><label>Link verified church<select name="resolved_unit_id" data-unit-search><option value="">Choose a verified church before approval</option><?php foreach($reviewChurches as $church): ?><option value="<?= (int)$church['id'] ?>"><?= e(unitLabel($church)) ?></option><?php endforeach ?></select></label><?php endif ?>
<button name="decision" value="approved" class="primary">Approve account</button><button name="decision" value="rejected" class="secondary">Reject</button></form></article><?php endforeach ?></div>
<?php if($pendingPages>1): ?><nav class="history-pagination" aria-label="Pending approval pages"><?php if($pendingPage>1): ?><a href="?page=representatives&amp;pending_page=<?= $pendingPage-1 ?>#pending-reps">← Previous</a><?php endif ?><span>Page <?= $pendingPage ?> of <?= $pendingPages ?></span><?php if($pendingPage<$pendingPages): ?><a href="?page=representatives&amp;pending_page=<?= $pendingPage+1 ?>#pending-reps">Next →</a><?php endif ?></nav><?php endif ?></section>
